INSERT INTO wp_posts (ID, post_author, post_date, post_date_gmt, post_content, post_title, post_excerpt, post_status, comment_status, ping_status, post_password, post_name, to_ping, pinged, post_modified, post_modified_gmt, post_content_filtered, post_parent, guid, menu_order, post_type, post_mime_type, comment_count) VALUES (101, 1, '2026-09-20 10:00:00', '2026-09-20 10:00:00', '<!-- wp:paragraph {"lead":true} -->
<p class="tour-intro">Khám phá hành trình <strong>Tour Du Lịch Nha Trang 4N3D: Dốc Lết - Đảo Khỉ - Tháp Bà Ponagar</strong> cùng Gonatour. Thời lượng <strong>4N3D (4 Ngày 3 Đêm)</strong>, khởi hành từ <strong>TP. Hồ Chí Minh</strong> với tiêu chuẩn lưu trú <strong>3* - 4*</strong>.</p>
<!-- /wp:paragraph -->

<!-- wp:heading -->
<h2>Điểm Nhấn Nổi Bật Của Chương Trình</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Chiêm ngưỡng cung đường biển Hòn Chồng - Núi Cô Tiên hoang sơ thơ mộng.</li><li>Tắm biển tại Dốc Lết với bờ cát mịn thoải dài và làn nước trong xanh màu ngọc bích.</li><li>Khám phá văn hóa Chămpa linh thiêng tại quần thể Tháp Bà Ponagar ngàn năm tuổi.</li><li>Tham quan Khu du lịch sinh thái Đảo Khỉ Hòn Lao, thưởng thức xiếc thú đặc sắc.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Xe du lịch máy lạnh 45 chỗ đời mới chất lượng cao phục vụ suốt tuyến.</li><li>Lưu trú: 3 đêm khách sạn 3-4 sao tại Nha Trang (2-3 khách/phòng).</li><li>Ăn uống theo chương trình: 4 bữa sáng + 6 bữa chính tiêu chuẩn 150.000đ/suất.</li><li>Vé vào cổng các điểm tham quan: Tháp Bà Ponagar, vé tàu Đảo Khỉ Hòn Lao.</li><li>Bảo hiểm du lịch nội địa mức đền bù tối đa 30.000.000 VND/người/vụ.</li><li>Nước suối tinh khiết 1 chai/người/ngày, nón du lịch cao cấp.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Chưa Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Chi phí cá nhân: giặt ủi, điện thoại, nước uống phát sinh ngoài chương trình.</li><li>Vé tắm bùn khoáng nóng I-Resort, vé cáp treo VinWonders.</li><li>Bữa tối ngày 3 để du khách tự do thưởng thức ẩm thực địa phương.</li><li>Thuế VAT 10% (nếu có nhu cầu xuất hóa đơn công ty).</li>
</ul>
<!-- /wp:list -->', 'Tour Du Lịch Nha Trang 4N3D: Dốc Lết - Đảo Khỉ - Tháp Bà Ponagar', 'Chiêm ngưỡng cung đường biển Hòn Chồng - Núi Cô Tiên hoang sơ thơ mộng.', 'publish', 'closed', 'closed', '', 'tour-du-lich-nha-trang-GNT4NHV-0112', '', '', '2026-09-20 10:00:00', '2026-09-20 10:00:00', '', 0, 'http://localhost/tours/tour-du-lich-nha-trang-GNT4NHV-0112', 0, 'tour', '', 0);
