INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5010, 101, '_tour_itinerary', '[{"day":1,"title":"NGÀY 1: TP.HCM – PHAN THIẾT – NHA TRANG (Ăn sáng, trưa, tối)","meals":{"summary":"Ăn sáng, trưa, tối","breakfast":true,"lunch":true,"dinner":true},"desc":"Sáng 05h30 xe và HDV đón đoàn tại điểm hẹn trung tâm TP.HCM khởi hành đi Nha Trang. Đoàn dùng bữa sáng tại Đồng Nai, trưa dừng chân dùng cơm tại Cà Ná ngắm biển tuyệt đẹp. Chiều đến Nha Trang, nhận phòng khách sạn 3-4 sao nghỉ ngơi. Tối thưởng thức ẩm thực phố biển, tự do dạo chợ đêm Nha Trang.","accommodation":"Khách sạn 3-4 sao trung tâm Nha Trang","transport":"Xe du lịch máy lạnh 45 chỗ"},{"day":2,"title":"NGÀY 2: BÃI BIỂN DỐC LẾT – THÁP BÀ PONAGAR – SUỐI KHOÁNG NÓNG (Ăn sáng, trưa, tối)","meals":{"summary":"Ăn sáng, trưa, tối","breakfast":true,"lunch":true,"dinner":true},"desc":"Sau bữa buffet sáng, xe đưa đoàn đến Bãi biển Dốc Lết, tự do tắm biển và thưởng thức hải sản tươi sống do ngư dân đánh bắt. Chiều viếng Tháp Bà Ponagar - kiệt tác kiến trúc văn hóa Chăm. Tham quan trung tâm bùn khoáng nóng I-Resort thư giãn hồi phục năng lượng. Dùng bữa tối đặc sản nem nướng Ninh Hòa.","accommodation":"Khách sạn 3-4 sao trung tâm Nha Trang","transport":"Xe du lịch máy lạnh"},{"day":3,"title":"NGÀY 3: KHÁM PHÁ ĐẢO KHỈ HÒN LAO – CHÙA LONG SƠN (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa (tối tự túc)","breakfast":true,"lunch":true,"dinner":false},"desc":"Đoàn đến bến tàu Đá Chồng lên tàu vượt vịnh Nha Phu đến KDL Đảo Khỉ Hòn Lao. Tự do tắm biển, giao lưu cùng hơn 1.200 chú khỉ tự nhiên. Dùng cơm trưa tại nhà hàng trên đảo. Chiều viếng Chùa Long Sơn chiêm bái tượng Kim Thân Phật Tổ cao 24m. Tối tự do khám phá ẩm thực đêm Nha Trang.","accommodation":"Khách sạn 3-4 sao trung tâm Nha Trang","transport":"Tàu du lịch + Xe du lịch"},{"day":4,"title":"NGÀY 4: CHỢ ĐẦM – VƯỜN NHO PHAN RANG – TP.HCM (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa","breakfast":true,"lunch":true,"dinner":false},"desc":"Đoàn ăn sáng, làm thủ tục trả phòng. Ghé Chợ Đầm mua đặc sản yến sào, mực rim me, cá ngựa. Khởi hành về Sài Gòn, ghé Phan Rang tham quan vườn nho bạt ngàn, thưởng thức rượu nho mật nho miễn phí. Chiều tối về đến TP.HCM, kết thúc chương trình du lịch.","accommodation":"Kết thúc chương trình","transport":"Xe du lịch máy lạnh 45 chỗ"}]');
