INSERT INTO wp_posts (ID, post_author, post_date, post_date_gmt, post_content, post_title, post_excerpt, post_status, comment_status, ping_status, post_password, post_name, to_ping, pinged, post_modified, post_modified_gmt, post_content_filtered, post_parent, guid, menu_order, post_type, post_mime_type, comment_count) VALUES (102, 1, '2026-09-20 10:00:00', '2026-09-20 10:00:00', '<!-- wp:paragraph {"lead":true} -->
<p class="tour-intro">Khám phá hành trình <strong>Tour Thái Lan 5N4D: Bangkok - Pattaya - Alcazar Show - Baiyoke Sky</strong> cùng Gonatour. Thời lượng <strong>5N4D (5 Ngày 4 Đêm)</strong>, khởi hành từ <strong>TP. Hồ Chí Minh (Sân bay Tân Sơn Nhất)</strong> với tiêu chuẩn lưu trú <strong>4* tiêu chuẩn Thái Lan</strong>.</p>
<!-- /wp:paragraph -->

<!-- wp:heading -->
<h2>Điểm Nhấn Nổi Bật Của Chương Trình</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Tặng vé đại tiệc Buffet quốc tế tại tòa nhà cao nhất Thái Lan Baiyoke Sky 86 tầng.</li><li>Thưởng thức Cafe phủ vàng hoàng gia và bánh ngọt dát vàng độc đáo.</li><li>Tặng vé xem chương trình tạp kỹ quốc tế Alcazar Cabaret Show tráng lệ tại Pattaya.</li><li>Dạo thuyền trên dòng sông huyền thoại Chaophraya, viếng Chùa Phật Vàng Wat Traimit 5.5 tấn.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Vé máy bay khứ hồi SGN - BKK - SGN gồm 20kg ký gửi và 7kg xách tay.</li><li>Thuế phi trường 2 nước, phí an ninh sân bay và phụ thu nhiên liệu.</li><li>Khách sạn 4 sao tiêu chuẩn Thái Lan (2 khách/phòng, lẻ nam/nữ ngủ phòng 3).</li><li>Các bữa ăn theo chương trình gồm 01 bữa buffet xoay 86 tầng Baiyoke Sky và BBQ hải sản.</li><li>Vé tham quan tất cả các thắng cảnh theo lịch trình kèm show diễn Alcazar.</li><li>Bảo hiểm du lịch quốc tế bồi thường tối đa 220.000.000 VND.</li><li>Hướng dẫn viên tiếng Việt phục vụ chu đáo suốt tuyến.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Chưa Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
