INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5030, 102, '_tour_itinerary', '[{"day":1,"title":"NGÀY 1: TP.HCM – BANGKOK (Ăn Tối)","meals":{"summary":"Ăn Tối","breakfast":false,"lunch":false,"dinner":true},"desc":"Trưởng đoàn đón khách tại ga quốc tế sân bay Tân Sơn Nhất đáp chuyến bay đi Bangkok. Xe và HDV địa phương đón đoàn đưa về nhận phòng khách sạn tại Bangkok. Dùng bữa tối tại nhà hàng lẩu Suki truyền thống.","accommodation":"Khách sạn 4 sao Bangkok (The Palazzo \/ Picnic)","transport":"Máy bay khứ hồi + Xe du lịch"},{"day":2,"title":"NGÀY 2: BANGKOK – LIGHTING ART MUSEUM – PATTAYA – CHÙA ĐẠI PHẬT (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa","breakfast":true,"lunch":true,"dinner":true},"desc":"Dùng buffet sáng, trả phòng. Khởi hành đi thành phố biển Pattaya. Tham quan Bảo tàng nghệ thuật ánh sáng Lighting Art Museum & Balloon Garden. Viếng Chùa Đại Phật Wat Phra Yai với tượng Phật cao 18m linh thiêng tọa lạc trên đỉnh đồi. Dùng bữa tối BBQ hải sản.","accommodation":"Khách sạn 4 sao Pattaya (Crystal Palace \/ Marble Garden)","transport":"Xe du lịch 45 chỗ đời mới"},{"day":3,"title":"NGÀY 3: ĐẢO CORAL – TRÂN BẢO PHẬT SƠN – ALCAZAR SHOW (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa","breakfast":true,"lunch":true,"dinner":true},"desc":"Đi cano cao tốc ra Đảo San Hô (Coral Island), tự do tắm biển hoặc tham gia nhảy dù biển, lặn ngắm san hô. Chiều viếng Trân Bảo Phật Sơn (Khao Chee Chan) ngọn núi khắc tượng Phật bằng 999kg vàng 24K. Tối thưởng thức đêm diễn tạp kỹ quốc tế hoành tráng Alcazar Show.","accommodation":"Khách sạn 4 sao Pattaya","transport":"Cano cao tốc + Xe du lịch"},{"day":4,"title":"NGÀY 4: PATTAYA – BAIYOKE SKY 86 TẦNG – TƯỢNG PHẬT 4 MẶT – BANGKOK (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa (tối tự túc)","breakfast":true,"lunch":true,"dinner":false},"desc":"Khởi hành về lại thủ đô Bangkok. Dùng đại tiệc Buffet quốc tế tại Baiyoke Sky 86 tầng ngắm toàn cảnh Bangkok. Chiều viếng Đền Erawan chiêm bái tượng Phật 4 Mặt linh hiển bậc nhất Thái Lan. Tự do mua sắm tại Central World, Big C Pratunam.","accommodation":"Khách sạn 4 sao Bangkok","transport":"Xe du lịch 45 chỗ"},{"day":5,"title":"NGÀY 5: DẠO THUYỀN CHAOPHRAYA – CHÙA PHẬT VÀNG – TP.HCM (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa","breakfast":true,"lunch":true,"dinner":false},"desc":"Dạo thuyền trên dòng sông Chaophraya huyền thoại ngắm cá nổi tâm linh. Viếng Wat Traimit chiêm ngưỡng tượng Phật bằng vàng nguyên khối nặng 5.5 tấn. Dùng bữa trưa trước khi ra sân bay Suvarnabhumi làm thủ tục bay về TP.HCM.","accommodation":"Kết thúc chương trình","transport":"Máy bay + Xe du lịch"}]');
