INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5038, 102, '_tour_inclusions', '["Vé máy bay khứ hồi SGN - BKK - SGN gồm 20kg ký gửi và 7kg xách tay.","Thuế phi trường 2 nước, phí an ninh sân bay và phụ thu nhiên liệu.","Khách sạn 4 sao tiêu chuẩn Thái Lan (2 khách\/phòng, lẻ nam\/nữ ngủ phòng 3).","Các bữa ăn theo chương trình gồm 01 bữa buffet xoay 86 tầng Baiyoke Sky và BBQ hải sản.","Vé tham quan tất cả các thắng cảnh theo lịch trình kèm show diễn Alcazar.","Bảo hiểm du lịch quốc tế bồi thường tối đa 220.000.000 VND.","Hướng dẫn viên tiếng Việt phục vụ chu đáo suốt tuyến."]');
INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5039, 102, '_tour_exclusions', '["Tiền Tip quy định bắt buộc cho HDV và tài xế: 700.000 VND\/khách\/tour.","Phụ thu phòng đơn đối với khách có nhu cầu ở riêng: 2.400.000 VND.","Hóa đơn VAT và chi phí phát sinh cá nhân ngoài chương trình."]');
INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5040, 102, '_tour_cancellation_terms', '[{"timeframe":"Sau khi đặt cọc","penalty_rate":"50% tiền cọc"},{"timeframe":"Trước 20 ngày khởi hành","penalty_rate":"50% tổng giá tour"},{"timeframe":"Trước 15 ngày khởi hành","penalty_rate":"75% tổng giá tour"},{"timeframe":"Dưới 15 ngày khởi hành","penalty_rate":"100% tổng giá tour"}]');
INSERT INTO wp_posts (ID, post_author, post_date, post_date_gmt, post_content, post_title, post_excerpt, post_status, comment_status, ping_status, post_password, post_name, to_ping, pinged, post_modified, post_modified_gmt, post_content_filtered, post_parent, guid, menu_order, post_type, post_mime_type, comment_count) VALUES (103, 1, '2026-09-20 10:00:00', '2026-09-20 10:00:00', '<!-- wp:paragraph {"lead":true} -->
<p class="tour-intro">Khám phá hành trình <strong>Tour Đà Nẵng - Bà Nà Hills - Cầu Vàng - Phố Cổ Hội An - Cố Đô Huế 4N3D</strong> cùng Gonatour. Thời lượng <strong>4N3D (4 Ngày 3 Đêm)</strong>, khởi hành từ <strong>TP. Hồ Chí Minh / Hà Nội</strong> với tiêu chuẩn lưu trú <strong>4* cao cấp</strong>.</p>
<!-- /wp:paragraph -->

<!-- wp:heading -->
<h2>Điểm Nhấn Nổi Bật Của Chương Trình</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Chinh phục Cầu Vàng - Bàn Tay Phật khổng lồ nổi tiếng toàn cầu tại đỉnh Bà Nà.</li><li>Dạo bước trong không gian hoài niệm đèn lồng lung linh của Di sản văn hóa thế giới Phố Cổ Hội An.</li><li>Tham quan Đại Nội Kinh Thành Huế và Lăng Khải Định kiệt tác lăng tẩm triều Nguyễn.</li><li>Khám phá Danh thắng Ngũ Hành Sơn huyền ảo và Làng đá mỹ nghệ Non Nước.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Vé máy bay khứ hồi bao gồm 7kg xách tay và 20kg ký gửi.</li><li>Xe du lịch tiện nghi phục vụ trọn vẹn theo lộ trình.</li><li>3 đêm khách sạn 4 sao (2 người/phòng, lẻ bố trí phòng 3).</li><li>Vé cáp treo Bà Nà Hills và buffet trưa Arapang.</li><li>Vé tham quan tất cả các điểm di tích: Ngũ Hành Sơn, Hội An, Đại Nội, Khải Định.</li><li>Vé nghe ca Huế trên sông Hương và thả hoa đăng.</li><li>Bảo hiểm du lịch mức 50.000.000 VND.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Chưa Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Chi phí phát sinh cá nhân, phòng đơn 1.600.000 VND, thuế VAT.</li>
</ul>
<!-- /wp:list -->', 'Tour Đà Nẵng - Bà Nà Hills - Cầu Vàng - Phố Cổ Hội An - Cố Đô Huế 4N3D', 'Chinh phục Cầu Vàng - Bàn Tay Phật khổng lồ nổi tiếng toàn cầu tại đỉnh Bà Nà.', 'publish', 'closed', 'closed', '', 'tour-da-nang-ba-na-hoi-an-hue-GNT4DNH-2026', '', '', '2026-09-20 10:00:00', '2026-09-20 10:00:00', '', 0, 'http://localhost/tours/tour-da-nang-ba-na-hoi-an-hue-GNT4DNH-2026', 0, 'tour', '', 0);
