INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5050, 103, '_tour_itinerary', '[{"day":1,"title":"NGÀY 1: ĐÀ NẴNG – BÁN ĐẢO SƠN TRÀ – NGŨ HÀNH SƠN – HỘI AN (Ăn trưa, tối)","meals":{"summary":"Ăn trưa, tối","breakfast":false,"lunch":true,"dinner":true},"desc":"Đón khách tại sân bay Đà Nẵng. Khởi hành tham quan Bán đảo Sơn Trà viếng Chùa Linh Ứng chiêm bái tượng Phật Bà cao 67m. Trưa dùng đặc sản bánh tráng cuốn thịt heo hai đầu da. Chiều tham quan Ngũ Hành Sơn, di chuyển sang Phố Cổ Hội An thả hoa đăng, thưởng thức cao lầu. Về Đà Nẵng nhận phòng khách sạn.","accommodation":"Khách sạn 4 sao biển Mỹ Khê Đà Nẵng","transport":"Xe du lịch máy lạnh"},{"day":2,"title":"NGÀY 2: SUN WORLD BÀ NÀ HILLS – CẦU VÀNG – BIỂN MỸ KHÊ (Ăn sáng, trưa, tối)","meals":{"summary":"Ăn sáng, trưa buffet, tối","breakfast":true,"lunch":true,"dinner":true},"desc":"Ăn sáng buffet. Xe đưa đoàn đến Bà Nà Hills, đi cáp treo đạt 4 kỷ lục thế giới. Check-in Cầu Vàng nổi tiếng, Làng Pháp, Hầm rượu Debay, Vườn hoa Le Jardin. Dùng buffet trưa hơn 100 món tại nhà hàng Arapang. Chiều về lại thành phố tắm biển Mỹ Khê, ngắm Cầu Rồng phun lửa về đêm.","accommodation":"Khách sạn 4 sao biển Mỹ Khê Đà Nẵng","transport":"Cáp treo + Xe du lịch"},{"day":3,"title":"NGÀY 3: ĐÀ NẴNG – ĐÈO HẢI VÂN – CỐ ĐÔ HUẾ – ĐẠI NỘI (Ăn sáng, trưa, tối)","meals":{"summary":"Ăn sáng, trưa, tối ca Huế","breakfast":true,"lunch":true,"dinner":true},"desc":"Đoàn khởi hành đi Huế xuyên hầm Hải Vân. Đến Huế, tham quan Đại Nội Hoàng Cung của 13 vị vua triều Nguyễn với Ngọ Môn, Điện Thái Hòa, Tử Cấm Thành. Chiều viếng Chùa Thiên Mụ cổ kính bên bờ sông Hương. Tối thưởng thức ca Huế trên thuyền rồng ngắm cầu Tràng Tiền.","accommodation":"Khách sạn 4 sao trung tâm Huế","transport":"Thuyền Rồng + Xe du lịch"},{"day":4,"title":"NGÀY 4: LĂNG KHẢI ĐỊNH – CHỢ ĐÔNG BA – TIỄN SÂN BAY (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa","breakfast":true,"lunch":true,"dinner":false},"desc":"Ăn sáng, tham quan Lăng Khải Định - đỉnh cao nghệ thuật khảm sành sứ độc nhất vô nhị. Ghé Chợ Đông Ba mua đặc sản mè xửng, tôm chua, trà cung đình. Trưa dùng bữa tại nhà hàng Huế trước khi xe đưa đoàn ra sân bay Đà Nẵng \/ Phú Bài làm thủ tục về lại.","accommodation":"Kết thúc chương trình","transport":"Xe du lịch máy lạnh"}]');
