INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5070, 104, '_tour_itinerary', '[{"day":1,"title":"NGÀY 1: TP.HCM – PHÚ QUỐC – DINH CẬU – GRAND WORLD (Ăn trưa, tối)","meals":{"summary":"Ăn trưa, tối","breakfast":false,"lunch":true,"dinner":true},"desc":"Đón khách tại sân bay Phú Quốc, ăn trưa với đặc sản gỏi cá trích trứ danh. Nhận phòng resort 4 sao nghỉ ngơi. Chiều viếng Dinh Cậu tâm linh, ngắm hoàng hôn biển Tây. Tối đến Grand World đi thuyền Gondola trên kênh đào Venice, xem show diễn thực cảnh Tinh Hoa Việt Nam.","accommodation":"Resort 4 sao Sunset Sanato \/ Novotel Phú Quốc","transport":"Máy bay + Xe du lịch"},{"day":2,"title":"NGÀY 2: CANO 4 ĐẢO – NGẮM SAN HÔ – CÁP TREO HÒN THƠM (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa","breakfast":true,"lunch":true,"dinner":true},"desc":"Lên cano cao tốc vượt sóng khám phá Hòn Móng Tay, Hòn Mây Rút Trong. Trải nghiệm lặn ngắm rạn san hô tự nhiên rực rỡ tại Hòn Gầm Ghì. Dùng bữa trưa hải sản trên đảo. Chiều trải nghiệm cáp treo vượt biển Hòn Thơm ngắm toàn cảnh quần đảo An Thới từ trên cao.","accommodation":"Resort 4 sao Phú Quốc","transport":"Cano cao tốc + Cáp treo Hòn Thơm"},{"day":3,"title":"NGÀY 3: NHÀ THÙNG NƯỚC MẮM – VƯỜN TIÊU – TIỄN SÂN BAY (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa","breakfast":true,"lunch":true,"dinner":false},"desc":"Ăn sáng, tắm biển sáng sớm. Tham quan nhà thùng nước mắm truyền thống Khải Hoàn hơn 40 độ đạm, vườn tiêu Suối Đá và cơ sở chế tác ngọc trai biển. Dùng bữa trưa trước khi xe đưa đoàn ra sân bay Phú Quốc đáp chuyến bay về lại.","accommodation":"Kết thúc chương trình","transport":"Xe du lịch máy lạnh"}]');
