INSERT INTO wp_posts (ID, post_author, post_date, post_date_gmt, post_content, post_title, post_excerpt, post_status, comment_status, ping_status, post_password, post_name, to_ping, pinged, post_modified, post_modified_gmt, post_content_filtered, post_parent, guid, menu_order, post_type, post_mime_type, comment_count) VALUES (105, 1, '2026-09-20 10:00:00', '2026-09-20 10:00:00', '<!-- wp:paragraph {"lead":true} -->
<p class="tour-intro">Khám phá hành trình <strong>Tour Hà Nội - Sapa 3N2Đ: Chinh Phục Đỉnh Fansipan - Bản Cát Cát - Đèo Ô Quy Hồ</strong> cùng Gonatour. Thời lượng <strong>3N2Đ (3 Ngày 2 Đêm)</strong>, khởi hành từ <strong>Hà Nội</strong> với tiêu chuẩn lưu trú <strong>3* - 4*</strong>.</p>
<!-- /wp:paragraph -->

<!-- wp:heading -->
<h2>Điểm Nhấn Nổi Bật Của Chương Trình</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Chinh phục nóc nhà Đông Dương Fansipan cao 3.143m ngắm biển mây bồng bềnh.</li><li>Dạo bước qua những thửa ruộng bậc thang kỳ vĩ tại Bản Cát Cát của người H’Mông.</li><li>Ngắm hoàng hôn ngoạn mục tại Đèo Ô Quy Hồ - một trong tứ đại đỉnh đèo Tây Bắc.</li><li>Thưởng thức đặc sản lẩu cá hồi, cá tầm và thắng cố Sapa trong tiết trời se lạnh.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Xe Limousine khứ hồi Hà Nội - Sapa - Hà Nội ghế ngả massage cao cấp.</li><li>Lưu trú 2 đêm khách sạn 3-4 sao trung tâm Sapa.</li><li>Vé cáp treo khứ hồi Fansipan Legend và tàu hỏa leo núi Mường Hoa.</li><li>Vé tham quan Bản Cát Cát, khu sinh thái Moana.</li><li>Các bữa ăn theo chương trình với ẩm thực Tây Bắc tươi ngon.</li><li>Bảo hiểm du lịch 40.000.000 VND.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Chưa Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Vé tàu hỏa leo đỉnh Fansipan chặng cuối (150.000đ), chi phí cá nhân, VAT.</li>
</ul>
<!-- /wp:list -->', 'Tour Hà Nội - Sapa 3N2Đ: Chinh Phục Đỉnh Fansipan - Bản Cát Cát - Đèo Ô Quy Hồ', 'Chinh phục nóc nhà Đông Dương Fansipan cao 3.143m ngắm biển mây bồng bềnh.', 'publish', 'closed', 'closed', '', 'tour-ha-noi-sapa-fansipan-cat-cat-GNT3SP-2026', '', '', '2026-09-20 10:00:00', '2026-09-20 10:00:00', '', 0, 'http://localhost/tours/tour-ha-noi-sapa-fansipan-cat-cat-GNT3SP-2026', 0, 'tour', '', 0);
