INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5090, 105, '_tour_itinerary', '[{"day":1,"title":"NGÀY 1: HÀ NỘI – CAO TỐC LÀO CAI – SAPA – BẢN CÁT CÁT (Ăn trưa, tối)","meals":{"summary":"Ăn trưa, tối","breakfast":false,"lunch":true,"dinner":true},"desc":"06h30 xe Limousine đón quý khách tại phố cổ Hà Nội khởi hành đi Sapa theo cao tốc Nội Bài - Lào Cai êm thuận. 12h30 đến Sapa, nhận phòng khách sạn dùng cơm trưa. Chiều bách bộ xuống Bản Cát Cát tìm hiểu văn hóa dệt thổ cẩm người H’Mông, check-in thác Tiên Sa. Tối tự do khám phá Nhà thờ Đá và chợ tình Sapa.","accommodation":"Khách sạn 3-4 sao trung tâm thị xã Sapa","transport":"Xe Limousine VIP"},{"day":2,"title":"NGÀY 2: CHINH PHỤC ĐỈNH FANSIPAN 3.143M – MOANA SAPA (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa","breakfast":true,"lunch":true,"dinner":true},"desc":"Ăn sáng tại khách sạn. Xe đưa đoàn đến ga cáp treo Fansipan Legend, trải nghiệm hệ thống cáp treo 3 dây hiện đại nhất thế giới. Chiêm bái Đại tượng Phật A Di Đà bằng đồng lớn nhất Việt Nam, chạm tay vào cột mốc Fansipan 3.143m. Chiều check-in khu sinh thái Moana Sapa với tượng Moana và hồ vô cực.","accommodation":"Khách sạn 3-4 sao Sapa","transport":"Cáp treo Fansipan + Xe ô tô"},{"day":3,"title":"NGÀY 3: ĐÈO Ô QUY HỒ – CỔNG TRỜI – LÀO CAI – HÀ NỘI (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa","breakfast":true,"lunch":true,"dinner":false},"desc":"Đoàn dùng buffet sáng, trả phòng. Khởi hành đi Đèo Ô Quy Hồ ngắm toàn cảnh dãy Hoàng Liên Sơn hùng vĩ từ Cổng Trời. Thưởng thức trứng nướng, cơm lam tại đỉnh đèo. Trưa ăn cơm tại nhà hàng trước khi lên xe Limousine về lại Hà Nội. 19h00 về đến điểm đón ban đầu.","accommodation":"Kết thúc chương trình","transport":"Xe Limousine VIP"}]');
