INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5110, 106, '_tour_itinerary', '[{"day":1,"title":"NGÀY 1: TP.HCM – MỸ THO – BẾN TRE – CẦN THƠ (Ăn sáng, trưa, tối)","meals":{"summary":"Ăn sáng, trưa cá tai tượng, tối du thuyền","breakfast":true,"lunch":true,"dinner":true},"desc":"07h00 đón khách tại TP.HCM đi Mỹ Tho. Thăm Chùa Vĩnh Tràng cổ kính. Lên thuyền du ngoạn sông Tiền ngắm tứ linh Long - Lân - Quy - Phụng. Sang Bến Tre đi xe ngựa trên đường làng, chèo xuồng ba lá qua rạch dừa nước. Dùng cơm trưa cá tai tượng chiên xù. Chiều về Cần Thơ nhận phòng. Tối lên du thuyền Ninh Kiều thưởng thức ẩm thực Tây Đô.","accommodation":"Khách sạn 3-4 sao trung tâm Cần Thơ","transport":"Xe du lịch + Thuyền du lịch sông Tiền + Xuồng ba lá"},{"day":2,"title":"NGÀY 2: CHỢ NỔI CÁI RĂNG – LÒ HỦ TIẾU – VƯỜN TRÁI CÂY – TP.HCM (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa","breakfast":true,"lunch":true,"dinner":false},"desc":"05h30 sáng lên thuyền đi Chợ Nổi Cái Răng ngắm cảnh mua bán nhộn nhịp trên sông qua cây bẹo đặc trưng. Thưởng thức hủ tiếu tô và cafe nổi trên thuyền. Ghé lò hủ tiếu truyền thống trải nghiệm làm pizza hủ tiếu. Thăm miệt vườn Mỹ Khánh rợp bóng trái cây. Chiều khởi hành về lại TP.HCM, kết thúc hành trình 2N1Đ ý nghĩa.","accommodation":"Kết thúc chương trình","transport":"Thuyền sông Hậu + Xe du lịch"}]');
