INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5118, 106, '_tour_inclusions', '["Xe du lịch chất lượng cao đưa đón trọn gói.","Khách sạn 3-4 sao trung tâm Cần Thơ giáp bến Ninh Kiều.","Thuyền du lịch Mỹ Tho, thuyền tham quan Chợ Nổi Cái Răng, xuồng chèo ba lá.","Vé tham quan tất cả các điểm trong lộ trình.","Bữa ăn tối sang trọng trên Du thuyền Cần Thơ.","Bảo hiểm du lịch 30.000.000 VND."]');
