INSERT INTO wp_posts (ID, post_author, post_date, post_date_gmt, post_content, post_title, post_excerpt, post_status, comment_status, ping_status, post_password, post_name, to_ping, pinged, post_modified, post_modified_gmt, post_content_filtered, post_parent, guid, menu_order, post_type, post_mime_type, comment_count) VALUES (107, 1, '2026-09-20 10:00:00', '2026-09-20 10:00:00', '<!-- wp:paragraph {"lead":true} -->
<p class="tour-intro">Khám phá hành trình <strong>Tour Singapore - Malaysia 4N3D: Marina Bay Sands - Sentosa - Malacca - Genting</strong> cùng Gonatour. Thời lượng <strong>4N3D (4 Ngày 3 Đêm)</strong>, khởi hành từ <strong>TP. Hồ Chí Minh</strong> với tiêu chuẩn lưu trú <strong>3* - 4*</strong>.</p>
<!-- /wp:paragraph -->

<!-- wp:heading -->
<h2>Điểm Nhấn Nổi Bật Của Chương Trình</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Khám phá kỳ quan kiến trúc Gardens by the Bay và cụm siêu cây Supertree Grove khổng lồ.</li><li>Check-in biểu tượng sư tử biển Merlion Park và tổ hợp nghỉ dưỡng đẳng cấp Marina Bay Sands.</li><li>Dạo bước trong khu phố cổ Di sản thế giới Malacca đậm đà phong cách Bồ Đào Nha - Hà Lan.</li><li>Trải nghiệm cáp treo lên cao nguyên Genting và vui chơi tại sòng bài casino hợp pháp hàng đầu Châu Á.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Vé máy bay khứ hồi SGN - SIN // KUL - SGN gồm thuế phí sân bay.</li><li>3 đêm khách sạn 3-4 sao chuẩn quốc tế (2 khách/phòng).</li><li>Xe đưa đón xuyên quốc gia máy lạnh tiện nghi đời mới.</li><li>Các bữa ăn theo lịch trình với món ăn đặc trưng Trung Hoa, Malaysia, Nyonya.</li><li>Vé cáp treo cao nguyên Genting và các điểm tham quan.</li><li>Bảo hiểm du lịch quốc tế quyền lợi 220.000.000 VND.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Chưa Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Tiền Tips phục vụ HDV và tài xế: 5 USD/khách/ngày (20 USD cả hành trình).</li><li>Phòng đơn phụ thu 3.100.000 VND, thuế VAT.</li>
</ul>
<!-- /wp:list -->', 'Tour Singapore - Malaysia 4N3D: Marina Bay Sands - Sentosa - Malacca - Genting', 'Khám phá kỳ quan kiến trúc Gardens by the Bay và cụm siêu cây Supertree Grove khổng lồ.', 'publish', 'closed', 'closed', '', 'tour-singapore-malaysia-4n3d-GSM4NTN-2409', '', '', '2026-09-20 10:00:00', '2026-09-20 10:00:00', '', 0, 'http://localhost/tours/tour-singapore-malaysia-4n3d-GSM4NTN-2409', 0, 'tour', '', 0);
