INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5130, 107, '_tour_itinerary', '[{"day":1,"title":"NGÀY 1: TP.HCM – SINGAPORE – GARDENS BY THE BAY – MARINA BAY (Ăn trưa, tối)","meals":{"summary":"Ăn trưa, tối","breakfast":false,"lunch":true,"dinner":true},"desc":"Trưởng đoàn đón khách tại ga quốc tế Tân Sơn Nhất đáp chuyến bay đi Singapore. Đến sân bay Changi, tham quan Thác nước Jewel Changi kỳ vĩ. Check-in Công viên Sư tử biển Merlion, Nhà hát Trái Sầu Riêng Esplanade. Chiều tham quan Gardens by the Bay. Tối thưởng thức show nhạc nước Spectra Light Show tại vịnh Marina Bay.","accommodation":"Khách sạn 3-4 sao trung tâm Singapore (Ibis \/ Oxford)","transport":"Máy bay + Xe du lịch quốc tế"},{"day":2,"title":"NGÀY 2: SINGAPORE – ĐẢO SENTOSA – CỬA KHẨU TUAS – PHỐ CỔ MALACCA (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa","breakfast":true,"lunch":true,"dinner":true},"desc":"Ăn sáng, xe đưa đoàn ra đảo Sentosa tham quan quả cầu Universal Studios, sòng bài Resorts World. Trưa di chuyển qua cửa khẩu Tuas nhập cảnh Malaysia. Khởi hành về thành phố cổ Malacca. Tham quan Quảng trường Hà Lan, Pháo đài cổ A Famosa, Nhà thờ Thánh Phaolô, dạo phố cổ Jonker Walk.","accommodation":"Khách sạn 4 sao Malacca (Heritage \/ Imperial)","transport":"Xe du lịch liên tuyến"},{"day":3,"title":"NGÀY 3: MALACCA – KUALA LUMPUR – CAO NGUYÊN GENTING – ĐỘNG BATU (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa","breakfast":true,"lunch":true,"dinner":true},"desc":"Khởi hành đi thủ đô Kuala Lumpur. Tham quan Động Batu với tượng thần Murugan mạ vàng cao 42.7m và 272 bậc thang rực rỡ sắc màu. Đi cáp treo chinh phục Cao nguyên giải trí Genting ở độ cao 2.000m mát mẻ. Chiều về lại Kuala Lumpur chiêm ngưỡng Tháp Đôi Petronas rực sáng về đêm.","accommodation":"Khách sạn 4 sao Kuala Lumpur (Cosmo \/ Swiss Garden)","transport":"Cáp treo Genting + Xe du lịch"},{"day":4,"title":"NGÀY 4: HOÀNG GIA MALAYSIA – QUẢNG TRƯỜNG ĐỘC LẬP – TP.HCM (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa","breakfast":true,"lunch":true,"dinner":false},"desc":"Ăn sáng buffet. Tham quan Cung điện Hoàng Gia Istana Negara nguy nga, Quảng trường Độc Lập Merdeka và Đài tưởng niệm Quốc Gia. Mua sắm đặc sản socola Beryl’s nổi tiếng thế giới. Sau bữa trưa, xe đưa đoàn ra sân bay quốc tế KLIA làm thủ tục bay về TP.HCM.","accommodation":"Kết thúc chương trình","transport":"Xe du lịch + Máy bay khứ hồi"}]');
