INSERT INTO wp_posts (ID, post_author, post_date, post_date_gmt, post_content, post_title, post_excerpt, post_status, comment_status, ping_status, post_password, post_name, to_ping, pinged, post_modified, post_modified_gmt, post_content_filtered, post_parent, guid, menu_order, post_type, post_mime_type, comment_count) VALUES (108, 1, '2026-09-20 10:00:00', '2026-09-20 10:00:00', '<!-- wp:paragraph {"lead":true} -->
<p class="tour-intro">Khám phá hành trình <strong>Tour Nhật Bản 5N5Đ: Tokyo - Núi Phú Sĩ - Tàu Shinkansen - Cố Đô Kyoto - Osaka</strong> cùng Gonatour. Thời lượng <strong>5N5Đ (5 Ngày 5 Đêm)</strong>, khởi hành từ <strong>TP. Hồ Chí Minh / Hà Nội</strong> với tiêu chuẩn lưu trú <strong>3* - 4* kèm 01 đêm Onsen</strong>.</p>
<!-- /wp:paragraph -->

<!-- wp:heading -->
<h2>Điểm Nhấn Nổi Bật Của Chương Trình</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Chinh phục biểu tượng thiêng liêng Núi Phú Sĩ - Di sản thế giới UNESCO.</li><li>Tặng trải nghiệm tắm suối khoáng nóng khoáng chất tự nhiên Onsen chuẩn truyền thống Nhật.</li><li>Trải nghiệm tốc độ tàu viên đạn siêu tốc Shinkansen niềm tự hào công nghệ xứ Phù Tang.</li><li>Khám phá Cố Đô Kyoto cổ kính với Chùa Vàng Kinkakuji và Đền nghìn cổng Fushimi Inari.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Vé máy bay khứ hồi SGN - NRT // KIX - SGN gồm 46kg ký gửi (2 kiện) và 10kg xách tay.</li><li>Visa du lịch nhập cảnh Nhật Bản diện đoàn du lịch trọn gói.</li><li>Lưu trú 4 sao (kèm 01 đêm khách sạn Onsen trải nghiệm tắm suối khoáng nóng).</li><li>Vé tàu cao tốc Shinkansen chặng Hamamatsu - Toyohashi hoặc tương đương.</li><li>Toàn bộ vé tham quan danh lam thắng cảnh và bữa ăn theo chương trình.</li><li>Bảo hiểm du lịch quốc tế bồi thường đến 1.050.000.000 VND (50.000 USD).</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Chưa Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Tiền Tips cho HDV và tài xế Nhật: 8 USD/khách/ngày (40 USD/tour).</li><li>Phụ thu phòng đơn 7.500.000 VND, thuế VAT, chi tiêu cá nhân.</li>
</ul>
<!-- /wp:list -->', 'Tour Nhật Bản 5N5Đ: Tokyo - Núi Phú Sĩ - Tàu Shinkansen - Cố Đô Kyoto - Osaka', 'Chinh phục biểu tượng thiêng liêng Núi Phú Sĩ - Di sản thế giới UNESCO.', 'publish', 'closed', 'closed', '', 'tour-nhat-ban-tokyo-phu-si-kyoto-osaka-NB5NTN-2409', '', '', '2026-09-20 10:00:00', '2026-09-20 10:00:00', '', 0, 'http://localhost/tours/tour-nhat-ban-tokyo-phu-si-kyoto-osaka-NB5NTN-2409', 0, 'tour', '', 0);
