INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5150, 108, '_tour_itinerary', '[{"day":1,"title":"ĐÊM 1 & NGÀY 1: TP.HCM – NARITA TOKYO – HOÀNG CUNG – GINZA (Ăn trưa, tối)","meals":{"summary":"Ăn trưa bò Nhật, tối","breakfast":false,"lunch":true,"dinner":true},"desc":"23h30 đêm trước tập trung tại sân bay Tân Sơn Nhất đáp chuyến bay đi Tokyo. Sáng đến sân bay Narita, xe đón đoàn tham quan Hoàng Cung Tokyo (Imperial Palace). Trưa thưởng thức bò Nhật nướng Teppanyaki. Chiều chiêm bái Chùa cổ Asakusa Kannon lâu đời nhất Tokyo, ngắm Tháp Tokyo Skytree, mua sắm tại phố sầm uất Ginza.","accommodation":"Khách sạn 3-4 sao Tokyo (Villa Fontaine \/ APA Resort)","transport":"Máy bay quốc tế + Xe du lịch Nhật"},{"day":2,"title":"NGÀY 2: TOKYO – NÚI PHÚ SĨ – LÀNG CỔ OSHINO HAKKAI – TẮM ONSEN (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa, tối Kaiseki","breakfast":true,"lunch":true,"dinner":true},"desc":"Ăn sáng, xe đưa đoàn đến Núi Phú Sĩ, di chuyển lên Trạm số 5 (tùy điều kiện thời tiết). Chiêm ngưỡng Làng cổ Oshino Hakkai thanh bình dưới chân núi với 8 hồ nước trong vắt từ tuyết tan. Tối nhận phòng tại khu nghỉ dưỡng suối nước nóng, mặc trang phục Yukata thưởng thức đại tiệc Kaiseki và tắm khoáng nóng Onsen.","accommodation":"Khách sạn Onsen truyền thống khu vực Phú Sĩ","transport":"Xe du lịch Nhật Bản"},{"day":3,"title":"NGÀY 3: TRẢI NGHIỆM TÀU SHINKANSEN – CỐ ĐÔ KYOTO – CHÙA VÀNG (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa","breakfast":true,"lunch":true,"dinner":true},"desc":"Đoàn trải nghiệm tàu siêu tốc Shinkansen tốc độ 300km\/h di chuyển đến Cố Đô Kyoto. Tham quan Chùa Vàng Kinkakuji dát vàng lấp lánh soi bóng trên mặt hồ gương. Dạo bước trong Rừng Trúc xanh ngắt Arashiyama thơ mộng. Chiều viếng Đền thờ Thần đạo Fushimi Inari Taisha với hơn 10.000 cổng Torii màu đỏ rực rỡ.","accommodation":"Khách sạn 4 sao Kyoto \/ Osaka","transport":"Tàu cao tốc Shinkansen + Xe du lịch"},{"day":4,"title":"NGÀY 4: CỐ ĐÔ KYOTO – OSAKA – LÂU ĐÀI OSAKA – SHINSAIBASHI (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa (tối tự túc)","breakfast":true,"lunch":true,"dinner":false},"desc":"Di chuyển về thành phố cảng năng động Osaka. Chụp ảnh lưu niệm bên ngoài Lâu đài Osaka uy nghiêm kiệt tác của Toyotomi Hideyoshi. Thưởng thức bữa trưa sushi và mì Udon truyền thống. Chiều tự do mua sắm và thưởng thức ẩm thực đường phố takoyaki tại thiên đường mua sắm sầm uất Shinsaibashi và Dotonbori.","accommodation":"Khách sạn 4 sao trung tâm Osaka","transport":"Xe du lịch đời mới"},{"day":5,"title":"NGÀY 5: SÂN BAY KANSAI OSAKA – TP. HỒ CHÍ MINH (Ăn sáng)","meals":{"summary":"Ăn sáng buffet","breakfast":true,"lunch":false,"dinner":false},"desc":"Đoàn dùng buffet sáng, làm thủ tục trả phòng. Xe đưa đoàn ra Sân bay quốc tế Kansai (KIX) làm thủ tục đáp chuyến bay thẳng về lại sân bay Tân Sơn Nhất TP.HCM. Trưởng đoàn hỗ trợ thủ tục nhập cảnh, kết thúc chuyến du xuân xứ sở mặt trời mọc.","accommodation":"Kết thúc chương trình","transport":"Xe du lịch + Máy bay khứ hồi"}]');
