INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5158, 108, '_tour_inclusions', '["Vé máy bay khứ hồi SGN - NRT \/\/ KIX - SGN gồm 46kg ký gửi (2 kiện) và 10kg xách tay.","Visa du lịch nhập cảnh Nhật Bản diện đoàn du lịch trọn gói.","Lưu trú 4 sao (kèm 01 đêm khách sạn Onsen trải nghiệm tắm suối khoáng nóng).","Vé tàu cao tốc Shinkansen chặng Hamamatsu - Toyohashi hoặc tương đương.","Toàn bộ vé tham quan danh lam thắng cảnh và bữa ăn theo chương trình.","Bảo hiểm du lịch quốc tế bồi thường đến 1.050.000.000 VND (50.000 USD)."]');
INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5159, 108, '_tour_exclusions', '["Tiền Tips cho HDV và tài xế Nhật: 8 USD\/khách\/ngày (40 USD\/tour).","Phụ thu phòng đơn 7.500.000 VND, thuế VAT, chi tiêu cá nhân."]');
INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5160, 108, '_tour_cancellation_terms', '[{"timeframe":"Sau khi nộp hồ sơ xin visa","penalty_rate":"100% lệ phí visa + cọc vé"},{"timeframe":"Trước 30 ngày khởi hành","penalty_rate":"50% giá tour"},{"timeframe":"Trước 15 ngày khởi hành","penalty_rate":"80% giá tour"},{"timeframe":"Dưới 10 ngày khởi hành","penalty_rate":"100% giá tour"}]');
INSERT INTO wp_posts (ID, post_author, post_date, post_date_gmt, post_content, post_title, post_excerpt, post_status, comment_status, ping_status, post_password, post_name, to_ping, pinged, post_modified, post_modified_gmt, post_content_filtered, post_parent, guid, menu_order, post_type, post_mime_type, comment_count) VALUES (109, 1, '2026-09-20 10:00:00', '2026-09-20 10:00:00', '<!-- wp:paragraph {"lead":true} -->
<p class="tour-intro">Khám phá hành trình <strong>Tour Hàn Quốc 5N4D: Seoul - Đảo Nami - Công Viên Everland - Cung Điện Gyeongbok</strong> cùng Gonatour. Thời lượng <strong>5N4D (5 Ngày 4 Đêm)</strong>, khởi hành từ <strong>TP. Hồ Chí Minh / Hà Nội</strong> với tiêu chuẩn lưu trú <strong>4* tiêu chuẩn Hàn Quốc</strong>.</p>
<!-- /wp:paragraph -->

<!-- wp:heading -->
<h2>Điểm Nhấn Nổi Bật Của Chương Trình</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Khám phá Đảo Nami xinh đẹp - phim trường tác phẩm kinh điển Bản Tình Ca Mùa Đông.</li><li>Vui chơi không giới hạn tại Công viên giải trí Everland thuộc top 10 công viên lớn nhất thế giới.</li><li>Check-in Cung điện Cảnh Phúc Gyeongbokgung, khoác lên mình trang phục Hanbok truyền thống.</li><li>Thưởng thức ẩm thực chuẩn Hàn: Gà hầm sâm Samgyetang, thịt nướng Bulgogi, lẩu kim chi.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Vé máy bay khứ hồi thẳng TP.HCM - Incheon - TP.HCM gồm 20kg ký gửi.</li><li>Lệ phí visa nhập cảnh Hàn Quốc.</li><li>4 đêm khách sạn 4 sao tiêu chuẩn Hàn Quốc (2 khách/phòng).</li><li>Vé vui chơi trọn gói công viên Everland và vé tham quan đảo Nami.</li><li>Các bữa ăn chuẩn hương vị xứ sở kim chi gồm gà hầm sâm, thịt nướng Bulgogi.</li><li>Bảo hiểm du lịch quốc tế bồi thường tối đa 220.000.000 VND.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Chưa Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Tiền Tip quy định bắt buộc cho HDV và tài xế: 7 USD/khách/ngày (35 USD/tour).</li><li>Phòng đơn phụ thu 3.800.000 VND, thuế VAT.</li>
</ul>
<!-- /wp:list -->', 'Tour Hàn Quốc 5N4D: Seoul - Đảo Nami - Công Viên Everland - Cung Điện Gyeongbok', 'Khám phá Đảo Nami xinh đẹp - phim trường tác phẩm kinh điển Bản Tình Ca Mùa Đông.', 'publish', 'closed', 'closed', '', 'tour-han-quoc-seoul-nami-everland-HQ5NSE-2026', '', '', '2026-09-20 10:00:00', '2026-09-20 10:00:00', '', 0, 'http://localhost/tours/tour-han-quoc-seoul-nami-everland-HQ5NSE-2026', 0, 'tour', '', 0);
