INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5170, 109, '_tour_itinerary', '[{"day":1,"title":"ĐÊM 1 & NGÀY 1: TP.HCM – INCHEON SEOUL – ĐẢO NAMI (Ăn sáng, trưa, tối)","meals":{"summary":"Ăn sáng canh sườn bò, trưa gà nướng, tối","breakfast":true,"lunch":true,"dinner":true},"desc":"Bay đêm từ sân bay Tân Sơn Nhất đi Seoul. Sáng hạ cánh sân bay Incheon, dùng bữa sáng canh sườn bò giải rượu Galbitang. Khởi hành đi Đảo Nami - hòn đảo hình bán nguyệt thơ mộng với những rặng ngân hạnh vàng rực. Thưởng thức gà nướng chảo thơm lừng. Chiều về Seoul nhận phòng khách sạn 4 sao nghỉ ngơi.","accommodation":"Khách sạn 4 sao Seoul (Bernoui \/ Golden City)","transport":"Máy bay quốc tế + Xe du lịch sưởi ấm"},{"day":2,"title":"NGÀY 2: CÔNG VIÊN GIẢI TRÍ EVERLAND – TRẢI NGHIỆM MẶC HANBOK (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa","breakfast":true,"lunch":true,"dinner":true},"desc":"Khám phá Công viên giải trí Everland với tàu lượn siêu tốc bằng gỗ T-Express ngoạn mục, vườn thú Safari hoang dã. Trưa thưởng thức thịt nướng than hoa Hàn Quốc. Chiều tham gia lớp học làm kim chi truyền thống và chụp ảnh lưu niệm trong trang phục Hanbok hoàng gia.","accommodation":"Khách sạn 4 sao Seoul","transport":"Xe du lịch 45 chỗ"},{"day":3,"title":"NGÀY 3: CUNG ĐIỆN GYEONGBOKGUNG – NHÀ XANH – THÁP NAMSAN (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa gà hầm sâm","breakfast":true,"lunch":true,"dinner":true},"desc":"Tham quan Cung điện Hoàng Gia Gyeongbokgung cổ kính 600 năm tuổi, xem nghi thức đổi gác của thị vệ triều Joseon. Chụp ảnh bên ngoài Nhà Xanh Cheongwadae (Phủ Tổng Thống). Trưa dùng gà hầm sâm thảo mộc bồi bổ sức khỏe. Chiều lên Tháp truyền hình Namsan chiêm ngưỡng hàng triệu ổ khóa tình yêu.","accommodation":"Khách sạn 4 sao Seoul","transport":"Xe du lịch máy lạnh"},{"day":4,"title":"NGÀY 4: TRUNG TÂM NHÂN SÂM CHÍNH PHỦ – MUA SẮM MYEONGDONG (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa (tối tự túc)","breakfast":true,"lunch":true,"dinner":false},"desc":"Tìm hiểu và mua sắm tại Trung tâm nhân sâm Hoàng Gia, Tinh dầu thông đỏ bảo bối sức khỏe Hàn Quốc. Dùng bữa trưa lẩu nấm kim chi. Chiều tự do mua sắm mỹ phẩm nội địa và thưởng thức ẩm thực vặt nức tiếng tại thiên đường mua sắm Myeongdong náo nhiệt.","accommodation":"Khách sạn 4 sao Seoul","transport":"Xe du lịch máy lạnh"},{"day":5,"title":"NGÀY 5: LÀNG BÍCH HỌA IHWA – INCHEON – TP. HỒ CHÍ MINH (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa","breakfast":true,"lunch":true,"dinner":false},"desc":"Tham quan Làng tranh bích họa Ihwa yên bình với những bậc thang nghệ thuật tuyệt đẹp. Ghé siêu thị Ponglim đóng gói hành lý và mua đặc sản bánh kẹo Hàn Quốc. Sau bữa trưa, xe đưa đoàn ra sân bay quốc tế Incheon đáp chuyến bay về TP.HCM.","accommodation":"Kết thúc chương trình","transport":"Xe du lịch + Máy bay khứ hồi"}]');
