INSERT INTO wp_posts (ID, post_author, post_date, post_date_gmt, post_content, post_title, post_excerpt, post_status, comment_status, ping_status, post_password, post_name, to_ping, pinged, post_modified, post_modified_gmt, post_content_filtered, post_parent, guid, menu_order, post_type, post_mime_type, comment_count) VALUES (110, 1, '2026-09-20 10:00:00', '2026-09-20 10:00:00', '<!-- wp:paragraph {"lead":true} -->
<p class="tour-intro">Khám phá hành trình <strong>Tour Châu Âu 4 Nước 10N9Đ: Pháp - Thụy Sỹ - Ý - Vatican Hành Trình Di Sản</strong> cùng Gonatour. Thời lượng <strong>10N9Đ (10 Ngày 9 Đêm)</strong>, khởi hành từ <strong>TP. Hồ Chí Minh / Hà Nội</strong> với tiêu chuẩn lưu trú <strong>4* tiêu chuẩn Châu Âu</strong>.</p>
<!-- /wp:paragraph -->

<!-- wp:heading -->
<h2>Điểm Nhấn Nổi Bật Của Chương Trình</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Chiêm ngưỡng tháp Eiffel biểu tượng nước Pháp và du thuyền lãng mạn trên dòng sông Seine.</li><li>Chinh phục đỉnh núi tuyết vĩnh cửu Titlis Thụy Sỹ ở độ cao 3.020m bằng cáp treo xoay 360 độ.</li><li>Lạc bước vào Venice - thành phố tình yêu trên sông không tiếng còi xe độc nhất vô nhị.</li><li>Khám phá Đấu trường La Mã Colosseum và Vương cung thánh đường St. Peter tại Tòa Thánh Vatican.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Vé máy bay quốc tế 5 sao khứ hồi (SGN - CDG // FCO - SGN) gồm thuế phí hàng không.</li><li>Lệ phí xin visa Schengen nhập cảnh Châu Âu.</li><li>Toàn bộ 8 đêm khách sạn 4 sao tiêu chuẩn Châu Âu cao cấp (2 khách/phòng).</li><li>Vé cáp treo xoay 360 độ lên đỉnh núi tuyết Titlis Thụy Sỹ.</li><li>Vé du thuyền sông Seine Paris và vé tàu sang đảo Venice.</li><li>Bảo hiểm du lịch quốc tế hạn mức tối đa 1.500.000.000 VND (50.000 EUR).</li><li>Các bữa ăn cao cấp xuyên suốt hành trình kết hợp ẩm thực Âu và Á.</li>
</ul>
<!-- /wp:list -->

<!-- wp:heading -->
<h2>Dịch Vụ Chưa Bao Gồm</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul>
    <li>Tiền Tip phục vụ tài xế và HDV Châu Âu: 10 EUR/khách/ngày (90 EUR/tour).</li><li>Phòng đơn phụ thu 16.500.000 VND, thuế VAT.</li>
</ul>
