INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5190, 110, '_tour_itinerary', '[{"day":1,"title":"NGÀY 1: TP.HCM – DOHA \/ DUBAI – THỦ ĐÔ PARIS (Ăn trên máy bay)","meals":{"summary":"Ăn uống tiêu chuẩn trên máy bay 5 sao","breakfast":false,"lunch":false,"dinner":false},"desc":"Quý khách có mặt tại sân bay Tân Sơn Nhất đáp chuyến bay của hãng hàng không 5 sao nối chuyến đi Paris hoa lệ. Nghỉ đêm trên máy bay.","accommodation":"Nghỉ đêm trên máy bay 5 sao","transport":"Máy bay quốc tế"},{"day":2,"title":"NGÀY 2: PARIS – THÁP EIFFEL – DU THUYỀN SÔNG SEINE – BẢO TÀNG LOUVRE (Ăn trưa, tối)","meals":{"summary":"Ăn trưa, tối ẩm thực Pháp","breakfast":true,"lunch":true,"dinner":true},"desc":"Hạ cánh sân bay Charles de Gaulle Paris. Tham quan Khải Hoàn Môn Arc de Triomphe, Đại lộ Champs-Élysées. Chụp ảnh lưu niệm tại Tháp Eiffel biểu tượng nước Pháp. Du thuyền Bateaux Parisiens trên sông Seine thơ mộng. Chiều chụp ảnh bên ngoài Bảo tàng Louvre với kim tự tháp kính nổi tiếng.","accommodation":"Khách sạn 4 sao Paris (Mercure \/ Novotel)","transport":"Du thuyền sông Seine + Xe bus Châu Âu"},{"day":3,"title":"NGÀY 3: PARIS – REIMS THỦ PHỦ RƯỢU VANG – LÀNG CỔ COLMAR (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa","breakfast":true,"lunch":true,"dinner":true},"desc":"Khởi hành đi Reims - thủ phủ vùng rượu sâm panh danh tiếng, viếng Nhà thờ Đức Bà Reims nơi đăng quang của 25 vị vua Pháp. Chiều di chuyển về Colmar - ngôi làng cổ tích đẹp nhất nước Pháp với những ngôi nhà nửa gỗ rực rỡ bên dòng kênh xanh Petite Venise.","accommodation":"Khách sạn 4 sao Colmar \/ Mulhouse","transport":"Xe bus đường dài Châu Âu"},{"day":4,"title":"NGÀY 4: COLMAR – THỤY SỸ – THÀNH PHỐ LUCERNE – CẦU GỖ CHAPEL (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa lẩu phô mai Fondue","breakfast":true,"lunch":true,"dinner":true},"desc":"Nhập cảnh Thụy Sỹ xinh đẹp, tiến về thành phố Lucerne cổ kính nép mình bên hồ nước trong xanh. Dạo bước trên Cầu gỗ Chapel thế kỷ 14 cổ nhất Châu Âu, chiêm ngưỡng Tượng đài Sư tử đá hấp hối tưởng niệm lính Thụy Sỹ. Thưởng thức đặc sản lẩu phô mai Fondue Thụy Sỹ.","accommodation":"Khách sạn 4 sao Lucerne \/ Engelberg","transport":"Xe du lịch Châu Âu"},{"day":5,"title":"NGÀY 5: NÚI TUYẾT TITLIS 3.020M – KINH ĐÔ THỜI TRANG MILAN Ý (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa","breakfast":true,"lunch":true,"dinner":true},"desc":"Chinh phục Đỉnh núi tuyết Titlis quanh năm tuyết trắng bằng cáp treo xoay 360 độ Rotair độc đáo. Đi bộ qua cầu treo cao nhất Châu Âu Titlis Cliff Walk. Trưa ăn cơm tại nhà hàng trên đỉnh núi. Chiều xuôi về nước Ý xinh đẹp, đến kinh đô thời trang Milan chiêm ngưỡng Thánh đường Duomo tráng lệ.","accommodation":"Khách sạn 4 sao Milan (Cosmo Palace \/ NH)","transport":"Cáp treo Titlis + Xe du lịch Ý"},{"day":6,"title":"NGÀY 6: MILAN – THÀNH PHỐ TRÊN SÔNG VENICE – THÁP NGHIÊNG PISA (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa mỳ Ý pizza","breakfast":true,"lunch":true,"dinner":true},"desc":"Lên thuyền vượt vịnh vào đảo Venice lãng mạn. Tham quan Quảng trường Thánh Marco, Dinh Tổng trấn Doge’s Palace, Cầu Than Thở Ponte dei Sospiri. Chiều di chuyển về vùng Tuscany đến thành phố Pisa chiêm ngưỡng Tháp nghiêng Pisa kỳ quan kiến trúc thế giới.","accommodation":"Khách sạn 4 sao Pisa \/ Florence","transport":"Thuyền Venice + Xe bus Châu Âu"},{"day":7,"title":"NGÀY 7: PISA – CỐ ĐÔ NGHỆ THUẬT FLORENCE – THỦ ĐÔ ROME (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa bò bít tết Bistecca","breakfast":true,"lunch":true,"dinner":true},"desc":"Tham quan Cố đô nghệ thuật phục hưng Florence (Firenze): Nhà thờ chính tòa Santa Maria del Fiore lộng lẫy, Cầu cổ Ponte Vecchio bắc qua sông Arno. Trưa thưởng thức bít tết Florence Bistecca alla Fiorentina. Chiều khởi hành về thủ đô Rome cổ kính.","accommodation":"Khách sạn 4 sao trung tâm Rome (Ergife \/ Holiday Inn)","transport":"Xe du lịch Châu Âu"},{"day":8,"title":"NGÀY 8: ĐẤU TRƯỜNG LA MÃ COLOSSEUM – ĐÀI PHUN NƯỚC TREVI (Ăn 3 bữa)","meals":{"summary":"Ăn 3 bữa","breakfast":true,"lunch":true,"dinner":true},"desc":"Tham quan Đấu trường La Mã Colosseum - biểu tượng hùng mạnh của Đế chế La Mã hơn 2.000 năm lịch sử. Khám phá Di chỉ Khảo cổ Roman Forum, Đền Pantheon kiệt tác mái vòm cổ đại. Thả đồng xu cầu nguyện may mắn tại Đài phun nước Trevi trứ danh và thưởng thức kem Gelato mát lạnh.","accommodation":"Khách sạn 4 sao Rome","transport":"Xe du lịch Rome"},{"day":9,"title":"NGÀY 9: CÔNG QUỐC VATICAN – VƯƠNG CUNG THÁNH ĐƯỜNG ST. PETER – SÂN BAY (Ăn sáng, trưa)","meals":{"summary":"Ăn sáng, trưa","breakfast":true,"lunch":true,"dinner":false},"desc":"Viếng thăm Quốc gia nhỏ nhất thế giới Vatican - trung tâm Giáo hội Công giáo toàn cầu. Chiêm bái Vương cung Thánh đường St. Peter tráng lệ kiệt tác của Michelangelo. Dùng bữa trưa trước khi xe đưa đoàn ra sân bay quốc tế Fiumicino Rome đáp chuyến bay về Việt Nam.","accommodation":"Nghỉ đêm trên máy bay","transport":"Xe du lịch + Máy bay quốc tế 5 sao"},{"day":10,"title":"NGÀY 10: VỀ ĐẾN TP. HỒ CHÍ MINH (Ăn trên máy bay)","meals":{"summary":"Ăn uống trên chuyến bay","breakfast":false,"lunch":false,"dinner":false},"desc":"Chuyến bay hạ cánh tại sân bay Tân Sơn Nhất TP.HCM. Trưởng đoàn hỗ trợ thủ tục nhập cảnh và nhận hành lý. Kết thúc chuyến hành trình khám phá Tây Âu 4 nước đầy ấn tượng.","accommodation":"Kết thúc chương trình","transport":"Máy bay quốc tế"}]');
