INSERT INTO wp_postmeta (meta_id, post_id, meta_key, meta_value) VALUES (5198, 110, '_tour_inclusions', '["Vé máy bay quốc tế 5 sao khứ hồi (SGN - CDG \/\/ FCO - SGN) gồm thuế phí hàng không.","Lệ phí xin visa Schengen nhập cảnh Châu Âu.","Toàn bộ 8 đêm khách sạn 4 sao tiêu chuẩn Châu Âu cao cấp (2 khách\/phòng).","Vé cáp treo xoay 360 độ lên đỉnh núi tuyết Titlis Thụy Sỹ.","Vé du thuyền sông Seine Paris và vé tàu sang đảo Venice.","Bảo hiểm du lịch quốc tế hạn mức tối đa 1.500.000.000 VND (50.000 EUR).","Các bữa ăn cao cấp xuyên suốt hành trình kết hợp ẩm thực Âu và Á."]');
